package android.opengl;
public class Matrix {
 public static void perspectiveM(float[] m,int off,float fov,float aspect,float near,float far){java.util.Arrays.fill(m,0);float f=1/(float)Math.tan(Math.toRadians(fov)/2);m[0]=f/aspect;m[5]=f;m[10]=(far+near)/(near-far);m[11]=-1;m[14]=2*far*near/(near-far);}
 public static void setLookAtM(float[] m,int o,float ex,float ey,float ez,float cx,float cy,float cz,float ux,float uy,float uz){float fx=cx-ex,fy=cy-ey,fz=cz-ez;float f=(float)Math.sqrt(fx*fx+fy*fy+fz*fz);fx/=f;fy/=f;fz/=f;float sx=fy*uz-fz*uy,sy=fz*ux-fx*uz,sz=fx*uy-fy*ux;float s=(float)Math.sqrt(sx*sx+sy*sy+sz*sz);sx/=s;sy/=s;sz/=s;ux=sy*fz-sz*fy;uy=sz*fx-sx*fz;uz=sx*fy-sy*fx;float[] v={sx,ux,-fx,0,sy,uy,-fy,0,sz,uz,-fz,0,-sx*ex-sy*ey-sz*ez,-ux*ex-uy*ey-uz*ez,fx*ex+fy*ey+fz*ez,1};System.arraycopy(v,0,m,o,16);}
 public static void multiplyMM(float[] out,int off,float[] a,int ao,float[] b,int bo){float[] tmp=new float[16];for(int c=0;c<4;c++)for(int r=0;r<4;r++)for(int k=0;k<4;k++)tmp[c*4+r]+=a[ao+k*4+r]*b[bo+c*4+k];System.arraycopy(tmp,0,out,off,16);}
 public static void multiplyMV(float[] out,int off,float[] m,int mo,float[] v,int vo){for(int r=0;r<4;r++){out[off+r]=0;for(int k=0;k<4;k++)out[off+r]+=m[mo+k*4+r]*v[vo+k];}}
 public static boolean invertM(float[] out,int o,float[] m,int mo){double[][] a=new double[4][8];for(int r=0;r<4;r++){for(int c=0;c<4;c++)a[r][c]=m[mo+c*4+r];a[r][r+4]=1;}for(int c=0;c<4;c++){int pivot=c;for(int r=c+1;r<4;r++)if(Math.abs(a[r][c])>Math.abs(a[pivot][c]))pivot=r;double[] t=a[c];a[c]=a[pivot];a[pivot]=t;if(Math.abs(a[c][c])<1e-12)return false;double d=a[c][c];for(int k=0;k<8;k++)a[c][k]/=d;for(int r=0;r<4;r++)if(r!=c){double f=a[r][c];for(int k=0;k<8;k++)a[r][k]-=f*a[c][k];}}for(int r=0;r<4;r++)for(int c=0;c<4;c++)out[o+c*4+r]=(float)a[r][c+4];return true;}
}
